**Step 2 – Basic Vitest test case for the constructor**

```ts
test('ZodMiniIntersection can be instantiated with a minimal definition', () => {
  // a *very* small definition that satisfies the shape expected by core.$ZodIntersection.init
  const minimalDef = {
    // the real Zod intersection definition contains many internal fields;
    // for the purpose of this unit‑test we only need to provide the fields that
    // the init functions read.  Supplying empty objects works because the init
    // functions only copy references.
    left: {} as any,
    right: {} as any,
    // the internal flag that tells Zod it is an intersection
    typeName: 'ZodIntersection' as const,
  } as unknown as core.$ZodIntersectionInternals<any, any>;

  const Intersection = ZodMiniIntersection; // the exported constructor
  const schema = new Intersection(minimalDef);

  expect(schema).toBeTruthy();
  // the instance should expose the base‑type methods (e.g. parse)
  expect(typeof (schema as any).parse).toBe('function');
});
```

